import { create } from 'zustand'
import { persist } from 'zustand/middleware'

export interface LevelStats {
  completedAt: string
}

export interface ProgressState {
  unlocked: string[]
  completed: Record<string, LevelStats>
}

export interface ProgressStore extends ProgressState {
  recordCompletion: (levelId: string) => void
  isLevelUnlocked: (levelId: string) => boolean
  isLevelCompleted: (levelId: string) => boolean
  resetProgress: () => void
}

const STORAGE_KEY = 'cyber-game-progress'
const STORAGE_VERSION = 1

function getNextLevelId(levelId: string): string | undefined {
  const num = Number.parseInt(levelId, 10)
  if (Number.isNaN(num)) return undefined
  return String(num + 1).padStart(2, '0')
}

function getInitialProgress(): ProgressState {
  return {
    unlocked: ['01'],
    completed: {},
  }
}

export const useProgressStore = create<ProgressStore>()(
  persist(
    (set, get) => ({
      ...getInitialProgress(),

      recordCompletion(levelId) {
        set((state) => {
          const completed = { ...state.completed, [levelId]: { completedAt: new Date().toISOString() } }
          const unlocked = new Set(state.unlocked)
          const next = getNextLevelId(levelId)
          if (next) {
            unlocked.add(next)
          }
          return { completed, unlocked: [...unlocked] }
        })
      },

      isLevelUnlocked(levelId) {
        return get().unlocked.includes(levelId)
      },

      isLevelCompleted(levelId) {
        return levelId in get().completed
      },

      resetProgress() {
        set(getInitialProgress())
      },
    }),
    {
      name: STORAGE_KEY,
      version: STORAGE_VERSION,
      partialize: (state) => ({
        unlocked: state.unlocked,
        completed: state.completed,
      }),
      migrate: (persistedState: unknown) => {
        if (typeof persistedState !== 'object' || persistedState === null) {
          return getInitialProgress()
        }
        const state = persistedState as Partial<ProgressState>
        return {
          unlocked: Array.isArray(state.unlocked) ? state.unlocked : ['01'],
          completed: state.completed ?? {},
        }
      },
    }
  )
)

import { Link } from 'react-router-dom'
import { useProgressStore } from '../store/progressStore.ts'
import { getLevel } from '../store/simulatorStore.ts'
import styles from './Home.module.css'

const LEVEL_IDS = ['01', '02', '03', '04']

export default function Home() {
  const { unlocked, completed } = useProgressStore()

  return (
    <div className={styles.home}>
      <h1>
        Cyber <span>Game</span>
      </h1>
      <p>通过可视化数据包流动，零基础理解网络攻防原理。{/* eslint-disable-line react/no-unescaped-entities */}</p>
      <div className={styles.actions}>
        {LEVEL_IDS.map((levelId) => {
          const level = getLevel(levelId)
          const isUnlocked = unlocked.includes(levelId)
          const isCompleted = levelId in completed
          const title = level?.meta.title ?? levelId
          if (!level) return null

          return isUnlocked ? (
            <Link
              key={levelId}
              to={`/level/${levelId}`}
              className={styles.primaryButton}
            >
              {title}
              {isCompleted && <span className={styles.badge}>已完成</span>}
            </Link>
          ) : (
            <span key={levelId} className={styles.lockedButton}>
              {title} 🔒
            </span>
          )
        })}
        <Link to="/sandbox" className={styles.secondaryButton}>
          沙盒模式
        </Link>
      </div>
    </div>
  )
}

