function getEveMac(simulator: Simulator): string | undefined {
  const eve = simulator.getDevice(LEVEL01_EVE_ID)
  const eveIface = [...(eve?.interfaces.values() ?? [])].find((iface) => iface.ip !== undefined)
  return eveIface?.mac
}

function getAliceArpGatewayMac(simulator: Simulator): string | undefined {
  const alice = simulator.getDevice(LEVEL01_ALICE_ID)
  return alice?.arpTable.get(LEVEL01_GATEWAY_IP)
}

function eveInterceptedPacketFromAlice(simulator: Simulator): boolean {
  const eve = simulator.getDevice(LEVEL01_EVE_ID)
  if (!eve || !(eve instanceof Host)) return false
  return eve.capturedPackets.some((packet) => packet.srcIp === LEVEL01_ALICE_IP)
}

function checkLevel01Objectives(
  simulator: Simulator,
  get: () => SimulatorStore,
): void {
  const eveMac = getEveMac(simulator)
  const aliceGatewayMac = getAliceArpGatewayMac(simulator)
  if (eveMac && aliceGatewayMac === eveMac) {
    get().markObjectiveCompleted('poison-alice')
  }

  if (eveInterceptedPacketFromAlice(simulator)) {
    get().markObjectiveCompleted('intercept')
  }
}

function checkLevel02Objectives(
  simulator: Simulator,
  get: () => SimulatorStore,
): void {
  const alice = simulator.getDevice('alice')
  const gateway = simulator.getDevice('gateway')
  const eve = simulator.getDevice(LEVEL01_EVE_ID)
  if (!alice || !gateway || !eve || !(eve instanceof Host)) return

  const gatewayMac = [...gateway.interfaces.values()].find((iface) => iface.ip !== undefined)?.mac
  const aliceGatewayMac = alice.arpTable.get(LEVEL01_GATEWAY_IP)

  // block-mitm：Alice 的网关 MAC 保持真实，且 Eve 没有捕获到 Alice 的非 ARP 包
  if (
    gatewayMac &&
    aliceGatewayMac === gatewayMac &&
    !eve.capturedPackets.some((packet) => packet.srcIp === LEVEL01_ALICE_IP && packet.protocol !== 'ARP')
  ) {
    get().markObjectiveCompleted('block-mitm')
  }

  // sniff-traffic：Alice 处于 promiscuous 模式且实际捕获到至少一个包

  // sniff-traffic：Alice 处于 promiscuous 模式且实际捕获到至少一个包
  if (
    alice instanceof Host &&
    alice.promiscuousInterfaces.size > 0 &&
    alice.capturedPackets.length > 0
  ) {
    get().markObjectiveCompleted('sniff-traffic')
  }

  // static-arp：Alice 配置了 Gateway IP 的静态 ARP
  if (alice.isStaticArp(LEVEL01_GATEWAY_IP)) {
    get().markObjectiveCompleted('static-arp')
  }
}

function checkLevel03Objectives(
  simulator: Simulator,
  get: () => SimulatorStore,
): void {
  const alice = simulator.getDevice(LEVEL03_ALICE_ID)
  const server = simulator.getDevice(LEVEL03_SERVER_ID)
  if (!alice || !server || !(alice instanceof Host) || !(server instanceof Host)) return

  // observe-handshake：Alice 与 Server 建立了任意一条 ESTABLISHED 连接
  if (
    alice.tcpConnections.some(
      (c) =>
        c.state === 'ESTABLISHED' &&
        c.remoteIp === LEVEL03_SERVER_IP &&
        c.remotePort === LEVEL03_SERVER_PORT,
    )
  ) {
    get().markObjectiveCompleted('observe-handshake')
  }

  // flood-server：服务器半开连接队列达到上限
  if (server.synBacklog.length >= server.maxSynBacklog) {
    get().markObjectiveCompleted('flood-server')
  }

  // enable-syn-cookie：服务器启用了 SYN Cookie
  if (server.synCookieEnabled) {
    get().markObjectiveCompleted('enable-syn-cookie')
  }

  // establish-under-attack：启用了 SYN Cookie 且 Alice 仍能建立连接
  if (
    server.synCookieEnabled &&
    alice.tcpConnections.some(
      (c) =>
        c.state === 'ESTABLISHED' &&
        c.remoteIp === LEVEL03_SERVER_IP &&
        c.remotePort === LEVEL03_SERVER_PORT,
    )
  ) {
    get().markObjectiveCompleted('establish-under-attack')
  }
}

function checkLevel04Objectives(
  simulator: Simulator,
  get: () => SimulatorStore,
): void {
  const alice = simulator.getDevice(LEVEL04_ALICE_ID)
  const server = simulator.getDevice(LEVEL04_SERVER_ID)
  const firewall = simulator.getDevice(LEVEL04_FIREWALL_ID)
  if (!alice || !server || !firewall || !(alice instanceof Host) || !(server instanceof Host) || !(firewall instanceof Firewall)) return

  const aliceEstablished = alice.tcpConnections.some(
    (c) =>
      c.state === 'ESTABLISHED' &&
      c.remoteIp === LEVEL04_SERVER_IP &&
      c.remotePort === LEVEL04_SERVER_PORT,
  )

  if (aliceEstablished) {
    get().markObjectiveCompleted('allow-internal-traffic')
  }

  const statefulEntry = firewall.connectionTracking.find(
    (entry) =>
      entry.protocol === 'TCP' &&
      entry.state === 'ESTABLISHED' &&
      entry.srcIp === LEVEL04_ALICE_IP &&
      entry.dstIp === LEVEL04_SERVER_IP &&
      entry.dstPort === LEVEL04_SERVER_PORT,
  )

  if (aliceEstablished && statefulEntry) {
    get().markObjectiveCompleted('verify-stateful')
  }

  const eveReachedServer = server.tcpConnections.some(
    (c) =>
      c.remoteIp === LEVEL04_EVE_IP,
  )

  if (firewall.aclRules.length > 0 && !eveReachedServer && server.synBacklog.length < server.maxSynBacklog) {
    get().markObjectiveCompleted('block-external-flood')
  }
}

