                } else {
                  const firstIface = selectedDeviceId
                    ? [...(simulator?.getDevice(selectedDeviceId)?.interfaces.values() ?? [])][0]?.id
                    : null
                  if (firstIface) store.startLink(firstIface)
                }
              }}
              disabled={!simulator || (!linkMode && !selectedDeviceId)}
            >
              {linkMode ? '取消连线' : '开始连线'}
            </button>
            {linkMode && <p className={styles.hint}>已选择源接口，点击目标设备完成连接。</p>}
          </div>

          {selectedDevice && (
            <div className={styles.panel}>
              <h3>设备配置：{selectedDevice.name}</h3>
              <div className={styles.field}>
                <label>名称</label>
                <input
                  value={deviceForm.name}
                  onChange={(e) => setDeviceForm({ ...deviceForm, name: e.target.value })}
                />
              </div>
              <div className={styles.field}>
                <label>IP</label>
                <input
                  value={deviceForm.ip}
                  onChange={(e) => setDeviceForm({ ...deviceForm, ip: e.target.value })}
                  placeholder="10.0.0.1"
                />
              </div>
              <div className={styles.field}>
                <label>子网掩码</label>
                <input
                  value={deviceForm.subnetMask}
                  onChange={(e) => setDeviceForm({ ...deviceForm, subnetMask: e.target.value })}
                  placeholder="255.255.255.0"
                />
              </div>
              <div className={styles.field}>
                <label>默认网关</label>
                <input
                  value={deviceForm.defaultGateway}
                  onChange={(e) => setDeviceForm({ ...deviceForm, defaultGateway: e.target.value })}
                  placeholder="10.0.0.254"
                />
              </div>
              <button className={styles.actionButton} onClick={handleUpdateDevice}>更新</button>
              <button
                className={styles.dangerButton}
                onClick={() => selectedDeviceId && store.removeDevice(selectedDeviceId)}
                style={{ marginTop: '0.5rem' }}
              >
                删除设备
              </button>

              {selectedDevice.interfaces.size > 0 && (
                <div className={styles.section} style={{ marginTop: '1rem' }}>
                  <div className={styles.hint}>接口（点击可开始/结束连线）</div>
                  {[...selectedDevice.interfaces.values()].map((iface) => (
                    <button
                      key={iface.id}
                      className={linkSource === iface.id ? styles.toolActive : styles.tool}
                      onClick={() => handleInterfaceClick(iface.id)}
                      style={{ marginTop: '0.25rem', textAlign: 'left' }}
                    >
                      {iface.id} {iface.linkId ? '(已连接)' : '(空闲)'}
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}

          <div className={styles.panel}>
            <h3>专家模式</h3>
            <textarea
              className={styles.script}
              value={script}
              onChange={(e) => setScript(e.target.value)}
            />
            <p className={styles.comingSoon}>脚本执行功能即将上线</p>
          </div>
        </aside>
      </div>
    </div>
  )
}
